<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import '../assets/courier-location-picker.css'
import { ArrowLeft, Check, LocateFixed, Minus, Plus } from 'lucide-vue-next'
const props = defineProps({ latitud: { type: [Number, String], default: null }, longitud: { type: [Number, String], default: null }, mode: { type: String, default: 'delivery' }, restaurant: { type: Object, default: null }, destination: { type: Object, default: null }, state: { type: String, default: 'ASIGNADO' }, saving: { type: Boolean, default: false } })
const emit = defineEmits(['cancel', 'confirm'])
const mapElement = ref(null); const latitude = ref(Number(props.latitud) || 13.6929); const longitude = ref(Number(props.longitud) || -89.2182); const locating = ref(false); const selectedLayer = ref('gray'); const isCourier = computed(() => props.mode === 'courier'); let map; let marker; let courierConnection; let referenceMarkers = []; let mapLayers = {}
function setPoint(lat, lon) { latitude.value = Number(lat.toFixed(6)); longitude.value = Number(lon.toFixed(6)); marker?.setLatLng([latitude.value, longitude.value]); if (courierConnection) courierConnection.setLatLngs([[latitude.value, longitude.value], courierConnection.getLatLngs()[1]]); map?.panTo([latitude.value, longitude.value]) }
function confirm() { emit('confirm', { latitud: latitude.value, longitud: longitude.value }) }
function changeLayer(layer) { if (!map || !mapLayers[layer] || selectedLayer.value === layer) return; Object.values(mapLayers).forEach((item) => item.remove()); mapLayers[layer].addTo(map); selectedLayer.value = layer }
function useLocation() { if (!navigator.geolocation) return; locating.value = true; navigator.geolocation.getCurrentPosition(({ coords }) => { setPoint(coords.latitude, coords.longitude); locating.value = false }, () => { locating.value = false }) }
onMounted(async () => { await nextTick(); map = L.map(mapElement.value, { zoomControl: false }).setView([latitude.value, longitude.value], props.latitud ? 17 : 13); const grayBase = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}', { attribution: 'Tiles &copy; Esri', maxZoom: 16 }); const grayLabels = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Reference/MapServer/tile/{z}/{y}/{x}', { attribution: 'Labels &copy; Esri', maxZoom: 16 }); const streets = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors', maxZoom: 19 }); const satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Imagery &copy; Esri', maxZoom: 19 }); const satelliteLabels = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}', { attribution: 'Labels &copy; Esri', maxZoom: 19 }); mapLayers = { gray: L.layerGroup([grayBase, grayLabels]), streets, satellite: L.layerGroup([satellite, satelliteLabels]) }; mapLayers.gray.addTo(map); L.control.zoom({ position: 'bottomright' }).addTo(map); const markerIcon = isCourier.value ? L.divIcon({ className: 'courier-location-marker', html: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/><path d="M7 17l3-8h4l3 8M10 9l-2-3M10 9h5l2 3"/></svg>', iconSize: [42, 42], iconAnchor: [21, 21] }) : undefined; marker = L.marker([latitude.value, longitude.value], { draggable: true, ...(markerIcon ? { icon: markerIcon } : {}) }).addTo(map); marker.on('dragend', () => { const point = marker.getLatLng(); setPoint(point.lat, point.lng) }); map.on('click', (event) => setPoint(event.latlng.lat, event.latlng.lng)); if (isCourier.value) { const refs = []; const restaurantPoint = [Number(props.restaurant?.pos_y), Number(props.restaurant?.pos_x)]; const destinationPoint = [Number(props.destination?.latitud), Number(props.destination?.longitud)]; if (Number.isFinite(restaurantPoint[0]) && Number.isFinite(restaurantPoint[1])) { referenceMarkers.push(L.circleMarker(restaurantPoint, { radius: 9, color: '#fff', weight: 3, fillColor: '#f20552', fillOpacity: 1 }).addTo(map).bindTooltip(`Recogida · ${props.restaurant?.nombre || 'Restaurante'}`, { permanent: true, direction: 'top', offset: [0, -8] })); refs.push(restaurantPoint) } if (Number.isFinite(destinationPoint[0]) && Number.isFinite(destinationPoint[1])) { referenceMarkers.push(L.circleMarker(destinationPoint, { radius: 9, color: '#fff', weight: 3, fillColor: '#1b1231', fillOpacity: 1 }).addTo(map).bindTooltip(`Entrega · ${props.destination?.detalle || 'Cliente'}`, { permanent: true, direction: 'top', offset: [0, -8] })); refs.push(destinationPoint) } const target = props.state === 'ASIGNADO' ? restaurantPoint : destinationPoint; if (Number.isFinite(target[0]) && Number.isFinite(target[1])) courierConnection = L.polyline([[latitude.value, longitude.value], target], { color: '#9a0c53', weight: 4, opacity: .9, dashArray: '8 7' }).addTo(map); if (refs.length) map.fitBounds(L.latLngBounds([...refs, [latitude.value, longitude.value]]), { padding: [35, 35], maxZoom: 15 }) } })
onBeforeUnmount(() => { referenceMarkers.forEach((item) => item.remove()); courierConnection?.remove(); map?.remove() })
</script>
<template><main class="location-picker"><header><button class="location-picker__back" :aria-label="isCourier ? 'Volver a la entrega activa' : 'Volver'" @click="emit('cancel')"><ArrowLeft :size="22" /><span v-if="isCourier">Volver a la entrega</span></button><strong>{{ isCourier ? 'Ubicación del repartidor' : 'Ubicación de entrega' }}</strong><span /></header><div ref="mapElement" class="location-picker__map" /><div class="location-picker__layers" aria-label="Capas del mapa"><button :class="{ active: selectedLayer === 'gray' }" @click="changeLayer('gray')">Gris</button><button :class="{ active: selectedLayer === 'streets' }" @click="changeLayer('streets')">Calles</button><button :class="{ active: selectedLayer === 'satellite' }" @click="changeLayer('satellite')">Satélite</button></div><section class="location-picker__sheet"><div class="location-picker__handle" /><h2>{{ isCourier ? 'Selecciona tu ubicación' : 'Selecciona el punto de entrega' }}</h2><p>{{ isCourier ? 'Mueve el marcador o toca el mapa para indicar desde dónde inicias la entrega.' : 'Mueve el marcador o toca el mapa para elegir la ubicación.' }}</p><div class="location-picker__coords">{{ latitude.toFixed(6) }}, {{ longitude.toFixed(6) }}</div><button class="location-picker__locate" :disabled="locating || saving" @click="useLocation"><LocateFixed :size="17" /> {{ locating ? 'Buscando…' : 'Usar mi ubicación actual' }}</button><button class="location-picker__confirm" :disabled="saving" @click="confirm"><Check :size="18" /> {{ saving ? 'Guardando ubicación…' : (isCourier ? 'Confirmar nueva ubicación' : 'Confirmar ubicación') }}</button><button v-if="isCourier" class="location-picker__cancel" @click="emit('cancel')">Salir de actualizar ubicación</button></section></main></template>

